package openapi

import (
	"strconv"
	"strings"

	"rn.m.vo7.io/vo7io/m/gocl/status/errcode"
)

// TODO: this type(s) must be generated by OpenAPI codegen.
//
//nolint:tagliatelle
type Error struct {
	CustomCode errcode.CustomErrorCode `json:"customCode"`
	CodeName   string                  `json:"codeName"`
	Message    string                  `json:"message"`
	Details    []any                   `json:"details"`
	Code       int                     `json:"code"`
}

func (e *Error) Error() string {
	if e == nil {
		return ""
	}

	res := e.Message
	det := make([]string, 0, 3) //nolint:mnd,revive

	if e.Code != 0 {
		det = append(det, strconv.FormatInt(int64(e.Code), 10))
	}

	if e.CodeName != "" {
		det = append(det, e.CodeName)
	}

	if e.CustomCode != "" {
		det = append(det, string(e.CustomCode))
	}

	if len(det) != 0 {
		res = res + " (" + strings.Join(det, ", ") + ")"
	}

	return res
}

func (e *Error) CustomErrorCode() errcode.CustomErrorCode {
	if e == nil {
		return ""
	}

	return e.CustomCode
}
